mapper.select:
SELECT b.id AS basecamp_id, b.title AS title, s.id AS spot_id, s.name AS spot_name, s.type AS spot_type, b.start_date AS start_date, b.end_date AS end_date, b.capacity AS capacity, AS headcount, b.status AS status, mine.relation AS my_relation FROM ( SELECT bm.basecamp_id AS basecamp_id, CASE bm.role WHEN 'LEADER' THEN 'LEADER' ELSE 'MEMBER' END AS relation FROM basecamp_member bm WHERE bm.member_id = #{memberId} AND bm.status = 'ACTIVE' UNION ALL SELECT ba.basecamp_id AS basecamp_id, 'APPLICANT' AS relation FROM basecamp_application ba WHERE ba.applicant_id = #{memberId} AND ba.status = 'PENDING' ) mine JOIN basecamp b ON b.id = mine.basecamp_id JOIN spot s ON s.id = b.spot_id
mine.relation = #{relation}
AND b.status = #{status}
ORDER BY b.start_date DESC, b.id DESC LIMIT #{limit} OFFSET #{offset}
